//! The tool-type catalogue the add dialog offers (etalii.adp spec 030, FR-021 and FR-035, task T048; data-model.md,
//! ToolType).
//!
//! The standalone host's own catalogue, `docs/tools.md` at 8b6ccfc, lists every tool type it knows in vendor groups,
//! each with its origin, display name, kind and state; `catalogue/tools.json` is that list, generated by
//! `tools/generate-parity-baseline.py`. Loading joins it, by origin, with the specification files every host uses,
//! under `vendor/etalii.adp/definitions/`: a `.dis` for a diagram type and a `.des` for a designer type, and the FBL
//! binding each names. The origin of a specification is its `language.origin`, or else the one its language id
//! carries (`net.etalii.adp.<vendor>.<type>`, as `definitions/diagrams/README.md` names them). A binding named by its
//! address in the standalone host's repository is read from its copy under `vendor/etalii.adp.ide.standalone/`
//! (`tools/vendor-standalone-bindings.py`).
//!
//! A tool type keeps the place, the name and the state the standalone host gives it, with or without a specification.
//! A specification that does not load lists its tool type with the findings and opens nothing (data-model.md). A
//! specification whose origin the standalone host does not list is kept apart, in [`Catalogue::unlisted`], since the
//! add dialog offers what the standalone host offers.

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

use serde::Deserialize;
use serde_json::Value as Json;

/// The standalone host's catalogue, as `tools/generate-parity-baseline.py` writes it.
const STANDALONE: &str = include_str!("../catalogue/tools.json");

/// The prefix of an address in the standalone host's repository, as the vendored specifications write it.
const STANDALONE_ADDRESS: &str = "https://raw.githubusercontent.com/etalii-adp/etalii.adp.ide.standalone/develop/";

/// The kind of tool a tool type is (docs/terminology.md).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ToolKind {
    Diagram,
    Designer,
    Editor,
}

/// How far the standalone host's support for a tool type has come, in the words of its `docs/tools.md`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ToolState {
    Identified,
    Specified,
    ToDo,
    WorkInProgress,
    Prototype,
    Implemented,
}

impl ToolState {
    /// The name `docs/tools.md` shows.
    pub fn label(self) -> &'static str {
        match self {
            ToolState::Identified => "Identified",
            ToolState::Specified => "Specified",
            ToolState::ToDo => "To-do",
            ToolState::WorkInProgress => "Work-in-progress",
            ToolState::Prototype => "Prototype",
            ToolState::Implemented => "Implemented",
        }
    }

    /// Whether the standalone host has a module for a tool type in this state; the others are an identity only.
    pub fn has_module(self) -> bool {
        self >= ToolState::WorkInProgress
    }
}

/// How bad a catalogue finding is: an error keeps the tool type from opening anything.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FindingSeverity {
    Warning,
    Error,
}

/// One thing loading a tool type's files found wrong, by the file and the JSON Pointer it is about.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CatalogueFinding {
    pub file: PathBuf,
    pub pointer: String,
    pub severity: FindingSeverity,
    pub message: String,
}

/// One tool type of the catalogue.
#[derive(Debug, Clone)]
pub struct ToolType {
    pub origin: String,
    pub display_name: String,
    pub kind: ToolKind,
    /// The vendor group `docs/tools.md` lists it under.
    pub group: String,
    pub state: ToolState,
    /// The `.dis` or `.des` file, when there is one.
    pub specification: Option<PathBuf>,
    /// The binding references the specification names (`file.fbl#name`, or an address), or the persistence plugin
    /// (`plugin:<name>`), in its order.
    pub bindings: Vec<String>,
    /// The binding files those references resolve to here, in the same order; a reference that resolves to no file
    /// is a warning of [`ToolType::findings`].
    pub binding_files: Vec<PathBuf>,
    /// The extensions it opens, lower case and with their dot, from its specification and its bindings.
    pub extensions: Vec<String>,
    /// Its first binding's claim is `registrationOnly` (FBL section 3): a body of it opens only through a registration,
    /// never by its extension (the agent behavior model's `.md`, which every Markdown file shares).
    pub registration_only: bool,
    /// Its first binding's claim is `shared` (FBL section 3): a body of it opens by its extension only when this marker
    /// matches, ahead of the extension's other owners, and never without one (the requirement document's envelope, on a
    /// `.md` that every Markdown file shares).
    pub shared_marker: Option<adp_fbl::documents::Marker>,
    pub shared: bool,
    pub findings: Vec<CatalogueFinding>,
}

impl ToolType {
    /// Whether it can open a document: it has a specification and nothing loading it found is an error.
    pub fn is_usable(&self) -> bool {
        self.specification.is_some() && !self.findings.iter().any(|f| f.severity == FindingSeverity::Error)
    }

    /// Whether it is usable and one of its extensions ends `name`, ignoring case.
    fn opens_by_extension(&self, name: &str) -> bool {
        let lower = name.to_lowercase();
        self.is_usable() && self.extensions.iter().any(|e| lower.ends_with(e.as_str()))
    }

    /// The vendor part of its origin (`c4` of `c4/container`).
    pub fn vendor(&self) -> &str {
        self.origin.split('/').next().unwrap_or_default()
    }
}

/// A specification file whose origin the standalone host's catalogue does not list.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnlistedSpecification {
    pub origin: String,
    pub file: PathBuf,
}

/// Every tool type, in the standalone host's order.
#[derive(Debug, Clone, Default)]
pub struct Catalogue {
    pub types: Vec<ToolType>,
    pub unlisted: Vec<UnlistedSpecification>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Listing {
    tool_types: Vec<Listed>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Listed {
    origin: String,
    display_name: String,
    kind: ToolKind,
    group: String,
    state: ToolState,
}

impl Catalogue {
    /// The standalone host's catalogue alone, without any specification joined.
    pub fn standalone() -> Catalogue {
        let listing: Listing = serde_json::from_str(STANDALONE).expect("catalogue/tools.json is the generator's JSON");
        Catalogue {
            types: listing
                .tool_types
                .into_iter()
                .map(|t| ToolType {
                    origin: t.origin,
                    display_name: t.display_name,
                    kind: t.kind,
                    group: t.group,
                    state: t.state,
                    specification: None,
                    bindings: Vec::new(),
                    binding_files: Vec::new(),
                    extensions: Vec::new(),
                    registration_only: false,
                    shared_marker: None,
                    shared: false,
                    findings: Vec::new(),
                })
                .collect(),
            unlisted: Vec::new(),
        }
    }

    /// The standalone host's catalogue joined with the specifications under `vendor`, the folder holding
    /// `etalii.adp/definitions/` and `etalii.adp.ide.standalone/`.
    pub fn load(vendor: &Path) -> Catalogue {
        let mut catalogue = Catalogue::standalone();
        let definitions = vendor.join("etalii.adp").join("definitions");
        for file in specification_files(&definitions) {
            let loaded = load_specification(&file, vendor);
            match catalogue.types.iter_mut().find(|t| t.origin == loaded.origin) {
                Some(tool_type) if tool_type.specification.is_none() => {
                    tool_type.specification = Some(file);
                    tool_type.bindings = loaded.bindings;
                    tool_type.binding_files = loaded.binding_files;
                    tool_type.extensions = loaded.extensions;
                    tool_type.registration_only = loaded.registration_only;
                    tool_type.shared_marker = loaded.shared_marker;
                    tool_type.shared = loaded.shared;
                    tool_type.findings = loaded.findings;
                }
                Some(tool_type) => tool_type.findings.push(CatalogueFinding {
                    file: file.clone(),
                    pointer: "/language".into(),
                    severity: FindingSeverity::Warning,
                    message: format!(
                        "A second specification of '{}' is left out; '{}' is the one loaded.",
                        loaded.origin,
                        tool_type
                            .specification
                            .as_deref()
                            .map(Path::display)
                            .map(|d| d.to_string())
                            .unwrap_or_default()
                    ),
                }),
                None => catalogue.unlisted.push(UnlistedSpecification {
                    origin: loaded.origin,
                    file,
                }),
            }
        }
        catalogue
    }

    /// The tool type of `origin`.
    pub fn by_origin(&self, origin: &str) -> Option<&ToolType> {
        self.types.iter().find(|t| t.origin == origin)
    }

    /// The tool types in their vendor groups, groups and tool types in the standalone host's order.
    pub fn groups(&self) -> Vec<(&str, Vec<&ToolType>)> {
        let mut groups: Vec<(&str, Vec<&ToolType>)> = Vec::new();
        for tool_type in &self.types {
            match groups.iter_mut().find(|(g, _)| *g == tool_type.group) {
                Some((_, members)) => members.push(tool_type),
                None => groups.push((&tool_type.group, vec![tool_type])),
            }
        }
        groups
    }

    /// The usable tool types that open a file named `name`, by its extension, in catalogue order; a tool type whose
    /// binding claims its bodies only through a registration, or shares its extension and is decided by its body's
    /// marker ([`Catalogue::for_body`]), is not one of them.
    pub fn for_file(&self, name: &str) -> Vec<&ToolType> {
        self.types
            .iter()
            .filter(|t| !t.registration_only && !t.shared && t.opens_by_extension(name))
            .collect()
    }

    /// The usable tool types that open the body `bytes` of a file named `name`: those whose shared claim's marker
    /// matches it, ahead of the extension's other owners, then [`Catalogue::for_file`] (FBL section 12.3; etalii.adp
    /// spec 036, research R6).
    pub fn for_body(&self, name: &str, bytes: &[u8]) -> Vec<&ToolType> {
        let mut found: Vec<&ToolType> = self
            .types
            .iter()
            .filter(|t| {
                t.shared
                    && t.opens_by_extension(name)
                    && t.shared_marker
                        .as_ref()
                        .is_some_and(|m| adp_fbl::routing::marker_matches(m, bytes))
            })
            .collect();
        found.extend(self.for_file(name));
        found
    }
}

/// Every `.dis` and `.des` file under `definitions`' kind folders, in name order.
fn specification_files(definitions: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for kind in ["diagrams", "designers", "editors"] {
        let Ok(entries) = fs::read_dir(definitions.join(kind)) else {
            continue;
        };
        let mut found: Vec<PathBuf> = entries
            .filter_map(|e| e.ok().map(|e| e.path()))
            .filter(|p| p.is_file() && matches!(p.extension().and_then(|e| e.to_str()), Some("dis" | "des")))
            .collect();
        found.sort();
        files.extend(found);
    }
    files
}

struct LoadedSpecification {
    origin: String,
    bindings: Vec<String>,
    binding_files: Vec<PathBuf>,
    extensions: Vec<String>,
    registration_only: bool,
    shared_marker: Option<adp_fbl::documents::Marker>,
    shared: bool,
    findings: Vec<CatalogueFinding>,
}

fn load_specification(file: &Path, vendor: &Path) -> LoadedSpecification {
    let mut loaded = LoadedSpecification {
        origin: String::new(),
        bindings: Vec::new(),
        binding_files: Vec::new(),
        extensions: Vec::new(),
        registration_only: false,
        shared_marker: None,
        shared: false,
        findings: Vec::new(),
    };
    let finding = |pointer: &str, severity, message: String| CatalogueFinding {
        file: file.to_path_buf(),
        pointer: pointer.into(),
        severity,
        message,
    };
    let bytes = match fs::read(file) {
        Ok(bytes) => bytes,
        Err(e) => {
            loaded.findings.push(finding(
                "",
                FindingSeverity::Error,
                format!("The file does not read: {e}"),
            ));
            return loaded;
        }
    };
    let root: Json = match serde_json::from_slice(&bytes) {
        Ok(root) => root,
        Err(e) => {
            loaded.findings.push(finding(
                "",
                FindingSeverity::Error,
                format!("The file is not JSON: {e}"),
            ));
            return loaded;
        }
    };
    let language = &root["language"];
    loaded.origin = match language["origin"].as_str() {
        Some(origin) => origin.to_owned(),
        None => language["id"]
            .as_str()
            .and_then(|id| id.strip_prefix("net.etalii.adp."))
            .map(|rest| rest.replacen('.', "/", 1))
            .unwrap_or_default(),
    };

    let mut extensions = BTreeSet::new();
    if let Some(extension) = language["fileExtension"].as_str() {
        extensions.insert(dotted(extension));
    }
    let persistence = &root["persistence"];
    if let Some(model) = persistence["files"]["model"].as_str()
        && let Some(extension) = model.strip_prefix("{name}")
        && extension.starts_with('.')
    {
        extensions.insert(extension.to_lowercase());
    }
    if let Some(plugin) = persistence["format"].as_str().filter(|f| f.starts_with("plugin:")) {
        loaded.bindings.push(plugin.to_owned());
    }
    let references: Vec<String> = match &persistence["binding"] {
        Json::String(one) => vec![one.clone()],
        _ => persistence["bindings"]
            .as_array()
            .map(|all| all.iter().filter_map(|b| b.as_str().map(str::to_owned)).collect())
            .unwrap_or_default(),
    };
    for reference in references {
        match binding_file(&reference, file, vendor) {
            Some(path) => {
                let (problems, document) = adp_fbl::documents::loader::load_file(&path);
                let name = reference.rsplit_once('#').map(|(_, n)| n).unwrap_or_default();
                match document.as_ref().and_then(|d| d.binding(name)) {
                    Some(binding) => {
                        extensions.extend(binding.claims.extensions.iter().map(|e| dotted(e)));
                        if loaded.binding_files.is_empty() {
                            loaded.registration_only = binding.claims.registration_only;
                            loaded.shared = binding.claims.shared;
                            loaded.shared_marker = binding.claims.marker.clone().filter(|_| binding.claims.shared);
                        }
                    }
                    None => loaded.findings.push(finding(
                        "/persistence",
                        FindingSeverity::Warning,
                        format!(
                            "The binding '{reference}' does not load: {}",
                            problems.iter().map(ToString::to_string).collect::<Vec<_>>().join("; ")
                        ),
                    )),
                }
                loaded.binding_files.push(path);
            }
            None => loaded.findings.push(finding(
                "/persistence",
                FindingSeverity::Warning,
                format!("The binding '{reference}' is not here."),
            )),
        }
        loaded.bindings.push(reference);
    }
    loaded.extensions = extensions.into_iter().collect();

    if file.extension().and_then(|e| e.to_str()) == Some("dis") {
        let result = adp_disl::DislLoader::load_bytes(&bytes, &adp_disl::DislPluginFunctions::none());
        loaded.findings.extend(result.diagnostics.into_iter().map(|d| {
            finding(
                &d.pointer,
                match d.severity {
                    adp_disl::DislSeverity::Error => FindingSeverity::Error,
                    adp_disl::DislSeverity::Warning => FindingSeverity::Warning,
                },
                d.message,
            )
        }));
    }
    loaded
}

/// The file a binding reference names: beside the specification, or the vendored copy of an address in the
/// standalone host's repository. A file named alone that is not beside the specification is the standalone host's,
/// which keeps it in its module's folder: the one file of that name in the vendored copy
/// (`tools/vendor-standalone-bindings.py`; `agent-behavior-modelling.fbl`).
fn binding_file(reference: &str, specification: &Path, vendor: &Path) -> Option<PathBuf> {
    let (file, _) = reference.rsplit_once('#')?;
    let standalone = vendor.join("etalii.adp.ide.standalone");
    let path = match file.strip_prefix(STANDALONE_ADDRESS) {
        Some(path) => standalone.join(path),
        None if file.contains("://") => return None,
        None => {
            let beside = specification.parent()?.join(file);
            if beside.is_file() || file.contains('/') {
                beside
            } else {
                named_in(&standalone.join("src"), file)?
            }
        }
    };
    path.is_file().then_some(path)
}

/// The first file named `name` under `folder`, its subfolders read in name order.
fn named_in(folder: &Path, name: &str) -> Option<PathBuf> {
    let mut entries: Vec<PathBuf> = fs::read_dir(folder).ok()?.flatten().map(|e| e.path()).collect();
    entries.sort();
    entries
        .iter()
        .find(|p| p.is_file() && p.file_name().is_some_and(|n| n == name))
        .cloned()
        .or_else(|| entries.iter().filter(|p| p.is_dir()).find_map(|p| named_in(p, name)))
}

fn dotted(extension: &str) -> String {
    let lower = extension.to_lowercase();
    if lower.starts_with('.') {
        lower
    } else {
        format!(".{lower}")
    }
}
